/** Map a programme's institution name to a ranking institution id. */
export function institutionIdForProgram(institution: string): string | null {
  const name = institution.toLowerCase();
  if (name.includes('university college london') || name === 'ucl') return 'ucl';
  if (name.includes('imperial')) return 'imperial';
  if (name.includes('national university of singapore')) return 'nus';
  if (name.includes('nanyang')) return 'ntu';
  return null;
}

/**
 * Display rule for institution names (language fix 2026-11-25): in zh-CN
 * show the verified Chinese name (name_zh) when one exists, else the
 * English official name; every other locale always shows the English
 * official name. Country names always come from the locale message files
 * (`country.<code>`), falling back to the English country_name from data.
 */
export function displayInstitutionName(inst: RankingInstitution, locale: string): string {
  if (locale === 'zh-CN' && inst.name_zh) return inst.name_zh;
  return inst.official_name;
}

export function displayCountryName(inst: { country: string; country_name: string }, t: (key: string) => string): string {
  const key = `country.${inst.country}`;
  const v = t(key);
  return v === key ? inst.country_name : v;
}

export function displayCountryCode(code: string, fallback: string, t: (key: string) => string): string {
  const key = `country.${code}`;
  const v = t(key);
  return v === key ? fallback : v;
}

/** Programme pages: the programme's institution string -> localised display name. */
export function displayProgramInstitutionName(institution: string, locale: string): string {
  const id = institutionIdForProgram(institution);
  if (!id) return institution;
  const inst = RANKING_INSTITUTIONS.find((i) => i.id === id);
  if (!inst) return institution;
  return displayInstitutionName(inst, locale);
}

